<section class="analytics-domain-section"><div class="analytics-domain-heading"><div><span>Bus Health</span><h2>Current bus status</h2></div></div><section class="analytics-kpi-strip"><x-analytics.kpi label="Active" :value="number_format($fleet['activeBuses']??0)" small="Available buses" icon="fa-bus" tone="green"/><x-analytics.kpi label="Maintenance" :value="number_format($fleet['underMaintenance']??0)" small="Under maintenance" icon="fa-screwdriver-wrench" tone="yellow"/><x-analytics.kpi label="Unavailable" :value="number_format($fleet['inactiveBuses']??0)" small="Inactive buses" icon="fa-circle-pause" tone="red"/><x-analytics.kpi label="Total Buses" :value="number_format($fleet['totalBuses']??0)" small="Bus Master List" icon="fa-bus-simple"/></section></section>